268	    public int bumpVersionIfOpen(String raceId, int expectedVersion) {
269	        return jdbcTemplate.update(
270	                "UPDATE race SET version = version + 1 "
271	                        + "WHERE race_id = ? AND version = ? AND status = 'OPEN'",
272	                raceId, expectedVersion);
273	    }
274	
275	    /**
276	     * 条件封榜：仅当赛事仍为 OPEN 且版本等于 expectedVersion 时转为 SEALED 并推进版本。
277	     *
278	     * @return 受影响行数；0 表示不存在、已封榜或版本不匹配
279	     */
280	    public int sealIfOpenAtVersion(String raceId, int expectedVersion, int newVersion) {
281	        return jdbcTemplate.update(
282	                "UPDATE race SET version = ?, status = 'SEALED' "
283	                        + "WHERE race_id = ? AND version = ? AND status = 'OPEN'",
284	                newVersion, raceId, expectedVersion);
285	    }
